/* ------------------------------------------------------------ date helpers
   All formatting uses UTC getters on purpose: the source
   timestamps are stored as UTC epoch ms that already encode the
   original wall-clock reading. Using UTC getters means the
   displayed time always matches the source data, no matter what
   timezone the viewer's browser is in. */

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const pad2 = (n) => String(n).padStart(2, "0");

function fmtFull(ts) {
  const d = new Date(ts);
  return `${pad2(d.getUTCDate())} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}, ${pad2(d.getUTCHours())}:${pad2(
    d.getUTCMinutes()
  )}:${pad2(d.getUTCSeconds())}`;
}

function fmtShort(ts) {
  const d = new Date(ts);
  return `${pad2(d.getUTCDate())} ${MONTHS[d.getUTCMonth()]}, ${pad2(d.getUTCHours())}:${pad2(d.getUTCMinutes())}`;
}

function fmtTick(ts, spanMs) {
  const d = new Date(ts);
  if (spanMs <= 2 * 3600 * 1000) {
    return `${pad2(d.getUTCHours())}:${pad2(d.getUTCMinutes())}:${pad2(d.getUTCSeconds())}`;
  }
  if (spanMs <= 30 * 3600 * 1000) {
    return `${pad2(d.getUTCHours())}:${pad2(d.getUTCMinutes())}`;
  }
  if (spanMs <= 9 * 24 * 3600 * 1000) {
    return `${pad2(d.getUTCDate())} ${MONTHS[d.getUTCMonth()]} ${pad2(d.getUTCHours())}:${pad2(d.getUTCMinutes())}`;
  }
  return `${pad2(d.getUTCDate())} ${MONTHS[d.getUTCMonth()]}`;
}

function toInputValue(ts) {
  const d = new Date(ts);
  return `${d.getUTCFullYear()}-${pad2(d.getUTCMonth() + 1)}-${pad2(d.getUTCDate())}T${pad2(d.getUTCHours())}:${pad2(
    d.getUTCMinutes()
  )}`;
}

function fromInputValue(str) {
  const [datePart, timePart] = str.split("T");
  const [y, m, d] = datePart.split("-").map(Number);
  const [hh, mm] = timePart.split(":").map(Number);
  return Date.UTC(y, m - 1, d, hh, mm, 0);
}

function fmtDur(ms) {
  const s = Math.round(ms / 1000);
  const days = Math.floor(s / 86400);
  const hrs = Math.floor((s % 86400) / 3600);
  const mins = Math.floor((s % 3600) / 60);
  if (days > 0) return `${days}d ${hrs}h`;
  if (hrs > 0) return `${hrs}h ${mins}m`;
  return `${mins}m`;
}

function stats(data, key) {
  let min = Infinity,
    max = -Infinity,
    sum = 0,
    n = 0,
    cur = null;
  for (const row of data) {
    const v = row[key];
    if (v === null || v === undefined || Number.isNaN(v)) continue;
    if (v < min) min = v;
    if (v > max) max = v;
    sum += v;
    n++;
    cur = v;
  }
  if (n === 0) return { min: 0, max: 0, avg: 0, cur: 0 };
  return { min, max, avg: sum / n, cur };
}

const fmtNum = (v) => (Math.abs(v) >= 1000 ? v.toFixed(0) : v.toFixed(1));

/* ------------------------------------------------------------
   SimpleLineChart — a tiny dependency-free SVG line chart.
   No recharts, no D3: just React + inline SVG.
   ------------------------------------------------------------ */

const VB_W = 1000;

function SimpleLineChart({ data, series, height = 120, highlightRange, spanMs }) {
  const wrapRef = useRef(null);
  const [hover, setHover] = useState(null); // { x, idx }

  const { minT, maxT, minV, maxV } = useMemo(() => {
    if (!data.length) return { minT: 0, maxT: 1, minV: 0, maxV: 1 };
    let mnV = Infinity,
      mxV = -Infinity;
    for (const row of data) {
      for (const s of series) {
        const v = row[s.key];
        if (v === null || v === undefined || Number.isNaN(v)) continue;
        if (v < mnV) mnV = v;
        if (v > mxV) mxV = v;
      }
    }
    if (mnV === Infinity) {
      mnV = 0;
      mxV = 1;
    }
    if (mnV === mxV) {
      mnV -= 1;
      mxV += 1;
    }
    return { minT: data[0].t, maxT: data[data.length - 1].t, minV: mnV, maxV: mxV };
  }, [data, series]);

  const padTop = height * 0.1;
  const padBottom = height * 0.1;
  const drawH = height - padTop - padBottom;

  const xOf = (t) => (maxT === minT ? 0 : ((t - minT) / (maxT - minT)) * VB_W);
  const yOf = (v) => padTop + (1 - (v - minV) / (maxV - minV)) * drawH;

  const paths = useMemo(() => {
    return series.map((s) => {
      let d = "";
      let started = false;
      for (const row of data) {
        const v = row[s.key];
        if (v === null || v === undefined || Number.isNaN(v)) {
          started = false;
          continue;
        }
        const x = xOf(row.t);
        const y = yOf(v);
        d += started ? ` L ${x.toFixed(2)},${y.toFixed(2)}` : `M ${x.toFixed(2)},${y.toFixed(2)}`;
        started = true;
      }
      return { key: s.key, color: s.color, d };
    });
  }, [data, series, minT, maxT, minV, maxV]);

  const handleMove = (e) => {
    if (!wrapRef.current || data.length === 0) return;
    const rect = wrapRef.current.getBoundingClientRect();
    const frac = Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width));
    const idx = Math.round(frac * (data.length - 1));
    setHover({ x: frac * rect.width, idx });
  };
  const handleLeave = () => setHover(null);

  const hoverRow = hover ? data[hover.idx] : null;

  return (
    <div ref={wrapRef} className="relative" onMouseMove={handleMove} onMouseLeave={handleLeave}>
      <svg
        viewBox={`0 0 ${VB_W} ${height}`}
        preserveAspectRatio="none"
        style={{ width: "100%", height, display: "block" }}
      >
        <line x1="0" y1={height - padBottom} x2={VB_W} y2={height - padBottom} stroke="#1f2b31" strokeWidth="1" />
        {highlightRange && (
          <rect
            x={xOf(highlightRange.start)}
            y={0}
            width={Math.max(0, xOf(highlightRange.end) - xOf(highlightRange.start))}
            height={height}
            fill="#22d3ee"
            fillOpacity="0.15"
          />
        )}
        {paths.map((p) => (
          <path key={p.key} d={p.d} fill="none" stroke={p.color} strokeWidth="2" vectorEffect="non-scaling-stroke" />
        ))}
        {hover && (
          <line x1={hover.x} y1="0" x2={hover.x} y2={height} stroke="#4b5a61" strokeWidth="1" strokeDasharray="3 3" />
        )}
      </svg>

      {hoverRow && (
        <div
          className="absolute top-0 z-10 rounded border border-neutral-800 bg-neutral-950 px-2.5 py-1.5 text-[11px] pointer-events-none"
          style={{
            left: Math.min(Math.max(hover.x, 70), (wrapRef.current?.clientWidth || 300) - 70),
            transform: "translateX(-50%)",
            fontFamily: "'JetBrains Mono', monospace",
          }}
        >
          <div className="text-neutral-500 mb-1">{fmtFull(hoverRow.t)}</div>
          {series.map((s) => (
            <div key={s.key} className="flex justify-between gap-3" style={{ color: s.color }}>
              <span>{M[s.key]?.label ?? s.key}</span>
              <span>{hoverRow[s.key] === null || hoverRow[s.key] === undefined ? "—" : fmtNum(hoverRow[s.key])}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function AxisTicks({ data, spanMs }) {
  if (data.length < 2) return null;
  const fracs = [0, 0.25, 0.5, 0.75, 1];
  return (
    <div className="flex justify-between mt-1 text-[10px] text-neutral-600" style={{ fontFamily: "'JetBrains Mono', monospace" }}>
      {fracs.map((f) => {
        const idx = Math.round(f * (data.length - 1));
        return <span key={f}>{fmtTick(data[idx].t, spanMs)}</span>;
      })}
    </div>
  );
}

/* ------------------------------------------------------------ cards */

function MiniCard({ mKey, data, spanMs, wide }) {
  const meta = M[mKey];
  const s = useMemo(() => stats(data, mKey), [data, mKey]);

  return (
    <div className={`rounded-lg border border-neutral-800 bg-neutral-900/40 p-4 ${wide ? "col-span-full" : ""}`}>
      <div className="flex items-start justify-between mb-1">
        <div className="text-neutral-400 text-xs tracking-wide">{meta.label}</div>
        <div className="text-neutral-600 text-[10px]">{meta.unit}</div>
      </div>
      <div
        className="text-neutral-50 mb-3"
        style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: wide ? 30 : 24, fontWeight: 600 }}
      >
        {fmtNum(s.cur)}
      </div>
      <SimpleLineChart data={data} series={[{ key: mKey, color: meta.color }]} height={wide ? 200 : 90} spanMs={spanMs} />
      {wide && <AxisTicks data={data} spanMs={spanMs} />}
      <div className="flex justify-between mt-2 text-[10px] text-neutral-500" style={{ fontFamily: "'JetBrains Mono', monospace" }}>
        <span>min {fmtNum(s.min)}</span>
        <span>avg {fmtNum(s.avg)}</span>
        <span>max {fmtNum(s.max)}</span>
      </div>
    </div>
  );
}

function ComboCard({ group, data, spanMs }) {
  const seriesList = group.metrics.map((k) => ({ key: k, color: M[k].color }));
  return (
    <div className="rounded-lg border border-neutral-800 bg-neutral-900/40 p-4">
      <div className="flex items-center gap-2 mb-3">
        <span className="h-3 w-1 rounded-sm flex-none" style={{ background: group.accent }} />
        <h3 className="text-neutral-200 text-sm font-medium">{group.title}</h3>
      </div>
      <SimpleLineChart data={data} series={seriesList} height={240} spanMs={spanMs} />
      <AxisTicks data={data} spanMs={spanMs} />
      <div className="flex flex-wrap gap-3 mt-3">
        {group.metrics.map((mKey) => {
          const s = stats(data, mKey);
          return (
            <div key={mKey} className="flex items-center gap-2 text-[11px]">
              <span className="h-2 w-2 rounded-full flex-none" style={{ background: M[mKey].color }} />
              <span className="text-neutral-400">{M[mKey].label}</span>
              <span className="text-neutral-100" style={{ fontFamily: "'JetBrains Mono', monospace" }}>
                {fmtNum(s.cur)}
              </span>
              <span className="text-neutral-600" style={{ fontFamily: "'JetBrains Mono', monospace" }}>
                ({fmtNum(s.min)}–{fmtNum(s.max)})
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* ------------------------------------------------------------ main page */

export default function SCRAnalyticsPage() {
  const [sessionKey, setSessionKey] = useState("A");
  const session = SESSIONS.find((s) => s.key === sessionKey);
  const fullData = session.data;

  const [startT, setStartT] = useState(fullData[0].t);
  const [endT, setEndT] = useState(fullData[fullData.length - 1].t);
  const [fromInput, setFromInput] = useState(toInputValue(fullData[0].t));
  const [toInput, setToInput] = useState(toInputValue(fullData[fullData.length - 1].t));

  const handleSessionChange = useCallback((key) => {
    setSessionKey(key);
    const s = SESSIONS.find((x) => x.key === key);
    const first = s.data[0].t;
    const last = s.data[s.data.length - 1].t;
    setStartT(first);
    setEndT(last);
    setFromInput(toInputValue(first));
    setToInput(toInputValue(last));
  }, []);

  const filtered = useMemo(() => fullData.filter((r) => r.t >= startT && r.t <= endT), [fullData, startT, endT]);

  const spanMs = endT - startT;
  const sessionSpanMs = fullData[fullData.length - 1].t - fullData[0].t;

  const applyPreset = (ms) => {
    const last = fullData[fullData.length - 1].t;
    const first = fullData[0].t;
    const newStart = Math.max(first, last - ms);
    setStartT(newStart);
    setEndT(last);
    setFromInput(toInputValue(newStart));
    setToInput(toInputValue(last));
  };

  const applyCustomRange = () => {
    const s = fromInputValue(fromInput);
    const e = fromInputValue(toInput);
    if (!Number.isNaN(s) && !Number.isNaN(e) && s < e) {
      setStartT(s);
      setEndT(e);
    }
  };

  const presets = [
    { label: "Last 1 Hour", ms: 3600 * 1000 },
    { label: "Last 6 Hours", ms: 6 * 3600 * 1000 },
    { label: "Last 24 Hours", ms: 24 * 3600 * 1000 },
    { label: "Last 3 Days", ms: 3 * 24 * 3600 * 1000 },
    { label: "Show All", ms: sessionSpanMs + 1 },
  ];

  return (
    <div
      className="min-h-screen w-full text-neutral-100"
      style={{ background: "#0c1013", fontFamily: "'Space Grotesk', sans-serif" }}
    >
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=JetBrains+Mono:wght@400;500;600&display=swap');`}</style>

      <div className="max-w-6xl mx-auto px-5 py-6">
        {/* header */}
        <div className="flex flex-wrap items-end justify-between gap-4 mb-5">
          <div>
            <div className="text-cyan-400 text-xs mb-1" style={{ fontFamily: "'JetBrains Mono', monospace" }}>
              SCR MONITORING
            </div>
            <h1 className="text-2xl font-semibold text-neutral-50">Diagnostics Analytics</h1>
          </div>

          <div className="flex gap-2">
            {SESSIONS.map((s) => (
              <button
                key={s.key}
                onClick={() => handleSessionChange(s.key)}
                className={`rounded border px-3 py-2 text-left transition-colors ${
                  sessionKey === s.key
                    ? "border-cyan-500 bg-cyan-500/10"
                    : "border-neutral-800 bg-neutral-900/40 hover:border-neutral-700"
                }`}
              >
                <div className={`text-xs font-medium ${sessionKey === s.key ? "text-cyan-300" : "text-neutral-300"}`}>
                  {s.label}
                </div>
                <div className="text-[10px] text-neutral-500" style={{ fontFamily: "'JetBrains Mono', monospace" }}>
                  {fmtShort(s.data[0].t)} → {fmtShort(s.data[s.data.length - 1].t)}
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* time range control */}
        <div className="rounded-lg border border-neutral-800 bg-neutral-900/40 p-5 mb-6">
          <div className="flex items-center gap-2 mb-1">
            <span className="h-3 w-1 rounded-sm flex-none bg-cyan-400" />
            <span className="text-neutral-200 text-sm font-medium">Time Range</span>
          </div>
          <p className="text-neutral-500 text-xs mb-4">
            Pick a quick range below, or set your own start and end date/time.
          </p>

          <div className="rounded border border-cyan-900/50 bg-cyan-500/5 px-4 py-3 mb-4">
            <div className="text-neutral-400 text-[11px] mb-1">Currently showing</div>
            <div className="text-neutral-50 text-sm break-words" style={{ fontFamily: "'JetBrains Mono', monospace" }}>
              {fmtFull(startT)} <span className="text-cyan-400">→</span> {fmtFull(endT)}
            </div>
            <div className="text-neutral-500 text-[11px] mt-1">
              {fmtDur(spanMs)} of data · {filtered.length} readings
            </div>
          </div>

          <div className="mb-4">
            <div className="text-neutral-400 text-[11px] mb-2">Quick range</div>
            <div className="flex flex-wrap gap-2">
              {presets.map((p) => (
                <button
                  key={p.label}
                  onClick={() => applyPreset(p.ms)}
                  className="rounded border border-neutral-800 bg-neutral-950/60 px-3 py-1.5 text-xs text-neutral-300 hover:border-cyan-600 hover:text-cyan-300 transition-colors"
                >
                  {p.label}
                </button>
              ))}
            </div>
          </div>

          <div>
            <div className="text-neutral-400 text-[11px] mb-2">Or pick your own dates</div>
            <div className="flex flex-wrap items-end gap-3">
              <div>
                <label className="block text-neutral-500 text-[10px] mb-1">From</label>
                <input
                  type="datetime-local"
                  value={fromInput}
                  min={toInputValue(fullData[0].t)}
                  max={toInputValue(fullData[fullData.length - 1].t)}
                  onChange={(e) => setFromInput(e.target.value)}
                  className="rounded border border-neutral-800 bg-neutral-950/60 px-2 py-1.5 text-xs text-neutral-200"
                />
              </div>
              <div>
                <label className="block text-neutral-500 text-[10px] mb-1">To</label>
                <input
                  type="datetime-local"
                  value={toInput}
                  min={toInputValue(fullData[0].t)}
                  max={toInputValue(fullData[fullData.length - 1].t)}
                  onChange={(e) => setToInput(e.target.value)}
                  className="rounded border border-neutral-800 bg-neutral-950/60 px-2 py-1.5 text-xs text-neutral-200"
                />
              </div>
              <button
                onClick={applyCustomRange}
                className="rounded bg-cyan-500/15 border border-cyan-600 px-4 py-1.5 text-xs text-cyan-300 hover:bg-cyan-500/25 transition-colors"
              >
                Apply
              </button>
            </div>
          </div>

          <div className="mt-5">
            <div className="text-neutral-400 text-[11px] mb-2">
              Full session at a glance — the highlighted part is what you're viewing below
            </div>
            <SimpleLineChart
              data={fullData}
              series={[{ key: "speed", color: "#4b5a61" }]}
              height={70}
              spanMs={sessionSpanMs}
              highlightRange={{ start: startT, end: endT }}
            />
            <AxisTicks data={fullData} spanMs={sessionSpanMs} />
          </div>
        </div>

        {/* groups */}
        <div className="space-y-8">
          {GROUPS.map((group) => (
            <section key={group.id}>
              <div className="flex items-center gap-2 mb-3">
                <span className="h-3 w-1 rounded-sm flex-none" style={{ background: group.accent }} />
                <h2 className="text-neutral-200 text-sm font-medium tracking-wide">{group.title}</h2>
                <div className="h-px flex-1 bg-neutral-800" />
              </div>

              {group.mode === "grid" ? (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                  {group.metrics.map((mKey) => (
                    <MiniCard key={mKey} mKey={mKey} data={filtered} spanMs={spanMs} wide={group.metrics.length === 1} />
                  ))}
                </div>
              ) : (
                <ComboCard group={group} data={filtered} spanMs={spanMs} />
              )}
            </section>
          ))}
        </div>

        <div className="text-center text-[11px] text-neutral-600 mt-8 pb-4">
          Units marked (raw) are placeholders — swap in your real sensor calibration in the{" "}
          <span style={{ fontFamily: "'JetBrains Mono', monospace" }}>M</span> table once known.
        </div>
      </div>
    </div>
  );
}